def version_key(s):
    """
    Convert a dot-separated version string into a tuple of integers,
    dropping any trailing zero components.
    If the version consists only of zeros, returns an empty tuple.
    """
    if not s:
        return ()
    parts = s.split('.')
    nums = []
    for p in parts:
        if p == '':
            continue
        nums.append(int(p))
    # Remove trailing zeros
    i = len(nums) - 1
    while i >= 0 and nums[i] == 0:
        i -= 1
    if i < 0:
        return ()
    return tuple(nums[:i+1])
